  const label = [...document.querySelectorAll('aside p')].map(p => p.textContent).find(t => t.includes('panel'));
  const signOut = !!document.querySelector('aside button');
  return JSON.stringify({ desktopSidebar: !!aside, panelLabel: label, signOutPresent: signOut, bannerStillTop: !!document.querySelector('[data-testid="demo-banner"]') })
})()

(() => new Promise(res => setTimeout(() => {
  const corner = document.querySelector('a[href="/login?as=student"] span.font-mono');
  const flag = [...document.querySelectorAll('.text-verdict-flag')].at(-1);
  let ratio = null;
  if (flag) {
    const fg = getComputedStyle(flag).color, bg = getComputedStyle(flag.parentElement).backgroundColor;
    ratio = fg + ' on ' + bg;
  }
  res(JSON.stringify({
    banner: document.querySelector('[data-testid="demo-banner"]')?.textContent.trim().slice(0, 50),
    cornerNumber: corner?.textContent,
    cornerColor: corner ? getComputedStyle(corner).color : null,
    flagStampSample: ratio,
    demoFeedHidden: document.querySelector('[data-testid="demo-qr-token"]')?.getAttribute('aria-hidden')
  }))
}, 1500)))()

